from produire import produire,paras,steps,table
from medicaments import antalgie
parts=[
('La {radiculopathie cervicale dégénérative} est une atteinte d’une racine nerveuse liée notamment à une hernie discale ou une sténose foraminale. Elle peut associer douleur du bras, paresthésies et déficit. Elle doit être distinguée d’une atteinte de la moelle.',paras('La douleur radiculaire peut exister sans déficit objectif. Une douleur cervicale irradiant vers l’épaule ne suffit donc pas à prouver une radiculopathie.', 'Le terme dégénératif suppose une concordance entre symptômes, examen et, lorsqu’elle est indiquée, imagerie. Les infections, tumeurs, traumatismes et neuropathies périphériques demandent un autre raisonnement.')),
('Le {contexte associe souvent douleur cervicale et brachiale}. Les étages cervicaux inférieurs sont fréquemment concernés. Beaucoup de formes non déficitaires évoluent favorablement avec un traitement conservateur.',paras('Le pronostic individuel dépend notamment de la fonction motrice, de l’évolution et d’une éventuelle atteinte médullaire associée. La fréquence de résolution décrite dans une série ne constitue pas une garantie.', 'Le délai de six à huit mois présenté dans une synthèse suisse de 2015 ne doit pas devenir une période d’attente obligatoire avant avis spécialisé. La gravité et l’impact fonctionnel priment.')),
('La {compression et l’inflammation radiculaires} peuvent contribuer ensemble à la douleur. Une hernie ou une réduction du foramen perturbe la racine. Le territoire atteint oriente la localisation mais comporte des variations.',paras('Une racine cervicale participe à plusieurs nerfs périphériques. Douleur, sensibilité, force et réflexes doivent donc être rapprochés, sans exiger un dessin parfaitement superposable à un dermatome.', 'Une compression centrale peut toucher aussi la moelle : des signes dans les jambes ou une maladresse bilatérale ne sont pas expliqués par une seule racine du bras.')),
('Le {tri recherche déficit moteur et myélopathie}. Une faiblesse nouvelle importante ou progressive impose un avis rapide. Trouble de marche, signes pyramidaux ou symptômes sphinctériens peuvent indiquer une atteinte médullaire.',paras('Urgence si progression aiguë, traumatisme instable suspecté ou contexte infectieux sévère. Fièvre, cancer, immunosuppression ou douleur inhabituelle persistante font rechercher une autre cause.', 'Ne pas traiter une douleur cervicobrachiale avec déficit évolutif par simple renouvellement d’antalgiques ou manipulation.')),
('L’{anamnèse localise douleur et perte de fonction}. Demander trajet dans le bras, engourdissement et gestes devenus difficiles. Préciser début, évolution, sommeil et facteurs déclenchants.',paras('Rechercher chute d’objets, difficulté à boutonner, troubles d’équilibre et symptômes dans les deux bras ou dans les jambes. Ces questions dépistent une myélopathie associée.', 'Demander traumatisme, cancer, infection, traitements anticoagulants et symptômes de l’épaule. Une douleur thoracique ou un malaise à l’effort exige de considérer une origine cardiovasculaire.')),
('L’{examen compare les deux côtés et les quatre membres}. Tester force segmentaire, sensibilité et réflexes. Examiner aussi épaules, nerfs périphériques et marche selon le tableau.',table(['Localisation possible','Exemples à confronter'],[['Racine C6.','Faiblesse de flexion du coude, troubles sensitifs vers le pouce ; diminution possible des réflexes bicipital ou styloradial.'],['Racine C7.','Faiblesse d’extension du coude, territoire vers le majeur et réflexe tricipital diminué.'],['Racine C8.','Atteinte possible de flexion des doigts et des muscles intrinsèques de la main, territoire vers les quatrième et cinquième doigts ; distinguer neuropathie périphérique.'],['Atteinte médullaire.','Signes pyramidaux, anomalie de marche, dextérité diminuée ; rechercher même si une douleur radiculaire existe.']])) ,
('L’{approche syndromique évite les faux raccourcis}. Une douleur du bras peut venir d’une racine, d’un nerf périphérique ou de l’épaule. Plusieurs atteintes peuvent coexister.',paras('Une neuropathie médiane ou ulnaire ne suit pas exactement la même distribution motrice et réflexe qu’une racine. Une affection de l’épaule peut limiter les mouvements par douleur sans déficit neurologique véritable.', 'Un test provocateur cervical peut soutenir l’hypothèse s’il est indiqué et réalisé prudemment. Ni sa positivité isolée ni sa négativité ne remplace l’ensemble de l’examen.')),
('Le {diagnostic repose sur la concordance}. Les signes cliniques orientent vers une racine et sa cause. Une protrusion discale découverte fortuitement ne prouve pas la responsabilité de cet étage.',paras('Noter précisément force, réflexes et sensibilité pour suivre l’évolution. La comparaison au contrôle est souvent plus utile qu’une étiquette générale de cervicalgie.', 'Une discordance entre symptômes et IRM impose de reprendre les diagnostics différentiels. Ne pas proposer un geste invasif uniquement parce que l’imagerie montre plusieurs anomalies.')),
('Les {examens dépendent du déficit et de l’évolution}. L’IRM est prioritaire devant suspicion de myélopathie ou déficit significatif progressif. Sans alarme, une radiculalgie récente ne nécessite pas toujours une imagerie immédiate.',paras('Une douleur persistante au-delà de quatre à six semaines malgré prise en charge fait discuter l’IRM, notamment si un geste invasif est envisagé. Ce délai ne s’applique pas à une aggravation neurologique.', 'L’électroneuromyographie peut aider si la localisation est incertaine ou si une neuropathie périphérique est envisagée. Elle ne remplace pas l’IRM dans une suspicion de compression médullaire.')),
('L’{algorithme sépare forme stable et atteinte évolutive}. Le traitement conservateur nécessite une surveillance documentée. L’apparition d’une faiblesse modifie le degré d’urgence.',steps('Identifier syndrome radiculaire et rechercher une atteinte médullaire.', 'Si déficit important, progressif ou autre alarme : imagerie et avis spécialisés rapides.', 'Si forme stable sans alarme : traitement symptomatique individualisé et activité adaptée.', 'Planifier contrôle de force, sensibilité, réflexes et fonction.', 'Si persistance limitante ou discordance : bilan ciblé et discussion spécialisée des options.')),
('La {prise en charge suisse est souvent conservatrice au départ}. Adapter temporairement les activités et proposer une rééducation prudente. Une chirurgie se discute selon déficit, concordance et persistance invalidante.',paras('@@MEDICAMENTS@@', 'Les corticoïdes systémiques ou infiltrations ne sont pas des traitements automatiques ; indication, bénéfice souvent limité et risques doivent être discutés. Aucune dose provenant d’une revue ou d’un protocole étranger n’est transformée en dose AIPS.', 'Une infiltration cervicale est un geste spécialisé avec risques propres et besoin d’imagerie pertinente. La décompression chirurgicale peut soulager plus rapidement certains patients sélectionnés, mais une image isolée ne suffit pas à l’indiquer.', 'La présence d’une myélopathie impose une stratégie distincte. Ne pas imposer plusieurs mois de physiothérapie avant d’examiner une dégradation motrice.')),
('Le {suivi mesure la récupération neurologique et fonctionnelle}. Réexaminer les déficits et leur évolution. Donner des consignes précises en cas d’aggravation.',paras('Nouvelle faiblesse, trouble de marche, troubles sphinctériens ou symptômes bilatéraux justifient un contact urgent. Une douleur croissante inhabituelle, de la fièvre ou des effets indésirables doivent aussi être réévalués.', 'Le retour aux charges et aux activités se fait progressivement. Éviter une immobilisation prolongée sans indication et les manipulations forcées non évaluées.')),
('Le {point clé} est la distinction entre racine et moelle. La plupart des formes stables permettent un traitement conservateur surveillé. Un déficit progressif ferme cette possibilité d’attente simple.',paras('La décision repose sur fonction, évolution et concordance, et non sur la seule taille d’une hernie. Le contrôle clinique doit être organisé dès la première consultation.'))]
quiz=[('Une douleur scapulaire suffit-elle à prouver une radiculopathie ?','Non.'),('La radiculalgie impose-t-elle un déficit moteur ?','Non.'),('Quel réflexe peut diminuer dans une atteinte C7 ?','Le réflexe tricipital, à interpréter avec les autres signes.'),('Une faiblesse progressive peut-elle attendre des mois ?','Non, avis et bilan rapides.'),('Pourquoi examiner les jambes ?','Pour rechercher une atteinte médullaire associée.'),('Une protrusion visible est-elle toujours responsable ?','Non, il faut une concordance.'),('Quelle imagerie étudie racines et moelle ?','L’IRM lorsqu’elle est indiquée.'),('Quand une exploration électrophysiologique peut-elle aider ?','Si la localisation est incertaine ou une neuropathie périphérique possible.'),('Faut-il un scanner immédiat pour toute radiculalgie récente ?','Non, sans alarme l’imagerie est ciblée.'),('Un test de Spurling isolé établit-il tout le diagnostic ?','Non.'),('Une infiltration est-elle un geste anodin de routine ?','Non, elle relève d’une indication spécialisée.'),('La chirurgie repose-t-elle uniquement sur l’image ?','Non.'),('Que documenter pour le suivi ?','Force, sensibilité, réflexes et retentissement fonctionnel.'),('Des mains maladroites avec marche anormale évoquent-elles une simple racine ?','Elles font rechercher une myélopathie.')]
produire(2,parts,quiz,(1,3,7,10,11,12,14),antalgie)
